/**
 * @distilled.cloud/hydradb -- HydraDB v2 API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model
 * that `scripts/convert.ts` converts from the OpenAPI document HydraDB
 * publishes at `https://docs.hydradb.com/api-reference/v2/openapi.json`,
 * mirrored at `specs/spec-mirror-hydradb/specs/openapi.json`. Everything
 * else in this folder is hand-written.
 *
 * Operations return the `data` of the API's `{ success, data, error, meta }`
 * envelope; the connector operations and `updateMetadataSchema`, which the
 * API answers without the envelope, return the body as sent. The API origin
 * defaults to `https://api.hydradb.com`; `HYDRADB_API_URL` or
 * `credentials({ apiBaseUrl })` points the SDK at an on-premises or
 * self-hosted deployment.
 *
 * @example
 * ```ts
 * import { Effect, Layer, Schedule } from "effect";
 * import * as FetchHttpClient from "effect/http/FetchHttpClient";
 * import * as HydraDB from "@distilled.cloud/hydradb";
 *
 * const program = Effect.gen(function* () {
 *   yield* HydraDB.getDatabaseStatus({ database: "acme_corp" }).pipe(
 *     Effect.repeat({
 *       until: ({ infra }) => infra?.ready_for_ingestion === true,
 *       schedule: Schedule.spaced("5 seconds"),
 *     }),
 *   );
 *
 *   const result = yield* HydraDB.query({
 *     database: "acme_corp",
 *     query: "What pricing tiers did product agree on?",
 *     type: "knowledge",
 *     query_by: "hybrid",
 *   });
 *   return typeof result === "string" ? result : (result.chunks ?? []);
 * });
 *
 * const Live = Layer.mergeAll(
 *   FetchHttpClient.layer,
 *   HydraDB.CredentialsFromEnv,
 *   HydraDB.HydraDBProtocol,
 * );
 *
 * program.pipe(Effect.provide(Live), Effect.runPromise).then(console.log);
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  API_VERSION,
  HydraDBProtocol,
  type HydraDBOpError,
  type HydraDBOpContext,
} from "./protocol.ts";
export * as Retry from "./retry.ts";
export * from "./services/hydradb.ts";
